// Singleton: contador de requests HTTP (como middleware)
const Stats = (() => {
  let instancia;

  function crearInstancia() {
    const datos = { requests: 0, errores: 0, inicio: Date.now() };
    return {
      registrarRequest() { datos.requests++; },
      registrarError()   { datos.errores++; },
      getStats() {
        return {
          ...datos,
          uptime: Math.round((Date.now() - datos.inicio) / 1000) + 's',
        };
      },
    };
  }

  return {
    getInstance() {
      if (!instancia) instancia = crearInstancia();
      return instancia;
    }
  };
})();

// Múltiples 'módulos' usando el mismo Stats:
const statsA = Stats.getInstance();
const statsB = Stats.getInstance();

statsA.registrarRequest();
statsA.registrarRequest();
statsB.registrarError();

console.log(statsA === statsB); // true
console.log(statsA.getStats()); // { requests: 2, errores: 1, ... }

// Factory: sistema de notificaciones
function crearNotificacion(tipo, mensaje, opciones = {}) {
  const base = {
    id: Math.random().toString(36).slice(2),
    mensaje,
    timestamp: new Date().toISOString(),
  };

  const estilos = {
    info:    { icono: 'ℹ️',  color: 'azul',  duracion: 3000 },
    exito:   { icono: '✅', color: 'verde', duracion: 3000 },
    error:   { icono: '❌', color: 'rojo',  duracion: 0 },    // 0 = no desaparece
    alerta:  { icono: '⚠️', color: 'naranja', duracion: 5000 },
  };

  if (!estilos[tipo]) throw new Error(`Tipo de notificación inválido: ${tipo}`);

  return { ...base, tipo, ...estilos[tipo], ...opciones };
}

const n1 = crearNotificacion('exito', 'Guardado correctamente');
const n2 = crearNotificacion('error', 'Sin conexión', { duracion: 10000 });

console.log(n1.icono, n1.color);
console.log(n2.duracion); // 10000 — opciones override el default

