const crearConfig = (() => {
  let instancia = null;

  return {
    getInstance() {
      if (!instancia) {
        instancia = { host: 'localhost', port: 3000, debug: false };
      }
      return instancia;
    }
  };
})();

const config1 = crearConfig.getInstance();
const config2 = crearConfig.getInstance();
const esMismaInstancia = config1 === config2;
const hostValue = config1.host;

console.log(esMismaInstancia, hostValue);

function crearValidador(tipo) {
  const validadores = {
    email: (v) => /^[^@]+@[^@]+\.[^@]+$/.test(v),
    telefono: (v) => /^\d{10}$/.test(v),
    password: (v) => v.length >= 8 && /[A-Z]/.test(v) && /\d/.test(v),
  };

  if (!validadores[tipo]) {
    throw new Error('Tipo de validador desconocido: ' + tipo);
  }

  return validadores[tipo];
}

const validarEmail = crearValidador('email');
const validarTel = crearValidador('telefono');

const emailOK = validarEmail('user@test.com');
const emailFail = validarEmail('no-email');
const telOK = validarTel('3001234567');

console.log(emailOK, emailFail, telOK);

function crearSistemaPlugins() {
  const registro = new Map();

  return {
    registrar(nombre, constructor) {
      registro.set(nombre, constructor);
    },
    crear(nombre, opciones = {}) {
      if (!registro.has(nombre)) {
        throw new Error(`Plugin no registrado: ${nombre}`);
      }
      return registro.get(nombre)(opciones);
    },
    listar() {
      return [...registro.keys()];
    },
  };
}

const plugins = crearSistemaPlugins();

// Registrar plugins
plugins.registrar('logger', ({ prefix = 'LOG' }) => ({
  log: (msg) => `${prefix}: ${msg}`,
}));

plugins.registrar('cache', ({ maxSize = 100 }) => ({
  datos: new Map(),
  maxSize,
}));

// Usar
const logger = plugins.crear('logger', { prefix: 'APP' });
const cache = plugins.crear('cache', { maxSize: 50 });

const mensajeLog = logger.log('Sistema iniciado');
const cacheMaxSize = cache.maxSize;
const pluginsDisponibles = plugins.listar();

console.log(mensajeLog, cacheMaxSize, pluginsDisponibles);
